const listarAusencias = `-- name: ListarAusencias :many
SELECT id, tecnico_id, inicio, fin, motivo, detalle, creada_por, anulada_en, anulada_por, version, created_at, updated_at FROM agenda.ausencias
WHERE tecnico_id = $1 AND fin > $2 AND inicio < $3
  AND ($4::boolean OR anulada_en IS NULL)
ORDER BY inicio, id
`

type ListarAusenciasParams struct {
	TecnicoID       int64
	Desde           time.Time
	Hasta           time.Time
	IncluirAnuladas bool
}

func (q *Queries) ListarAusencias(ctx context.Context, arg ListarAusenciasParams) ([]AgendaAusencia, error) {
	rows, err := q.db.Query(ctx, listarAusencias,
		arg.TecnicoID,
		arg.Desde,
		arg.Hasta,
		arg.IncluirAnuladas,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AgendaAusencia
	for rows.Next() {
		var i AgendaAusencia
		if err := rows.Scan(
			&i.ID,
			&i.TecnicoID,
			&i.Inicio,
			&i.Fin,
			&i.Motivo,
			&i.Detalle,
			&i.CreadaPor,
			&i.AnuladaEn,
			&i.AnuladaPor,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

