const solapes = `-- name: Solapes :many
SELECT c.orden_id, o.numero, o.empresa_id, c.inicio, c.fin
FROM agenda.citas c
JOIN campo.ordenes o ON o.id = c.orden_id
WHERE c.tecnico_id = $1 AND c.orden_id <> $2
  AND o.estado IN ('programada', 'en_camino', 'en_sitio', 'pausada')
  AND c.inicio < $3 AND c.fin > $4
ORDER BY c.inicio
`

type SolapesParams struct {
	TecnicoID int64
	OrdenID   int64
	Fin       time.Time
	Inicio    time.Time
}

type SolapesRow struct {
	OrdenID   int64
	Numero    string
	EmpresaID *int64
	Inicio    time.Time
	Fin       time.Time
}

// Citas del técnico que ocupan su agenda (orden programada, en camino, en sitio o pausada) y se
// cruzan con [inicio, fin).
func (q *Queries) Solapes(ctx context.Context, arg SolapesParams) ([]SolapesRow, error) {
	rows, err := q.db.Query(ctx, solapes,
		arg.TecnicoID,
		arg.OrdenID,
		arg.Fin,
		arg.Inicio,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SolapesRow
	for rows.Next() {
		var i SolapesRow
		if err := rows.Scan(
			&i.OrdenID,
			&i.Numero,
			&i.EmpresaID,
			&i.Inicio,
			&i.Fin,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

