// Consultas de agenda (sqlc → internal/agenda/bd).
// Usuarios, empresas y alcances (lectura de nucleo) ----------------------------------
func (q *Queries) UsuarioParaTecnico(ctx context.Context, id int64) (UsuarioParaTecnicoRow, error) {
	row := q.db.QueryRow(ctx, usuarioParaTecnico, id)
	var i UsuarioParaTecnicoRow
	err := row.Scan(
		&i.ID,
		&i.Nombre,
		&i.Correo,
		&i.Tipo,
		&i.Activo,
	)
	return i, err
}

const usuariosDeCuadrilla = `-- name: UsuariosDeCuadrilla :many
SELECT usuario_id FROM agenda.tecnicos WHERE cuadrilla_id = $1
`

func (q *Queries) UsuariosDeCuadrilla(ctx context.Context, cuadrillaID *int64) ([]int64, error) {
	rows, err := q.db.Query(ctx, usuariosDeCuadrilla, cuadrillaID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var usuario_id int64
		if err := rows.Scan(&usuario_id); err != nil {
			return nil, err
		}
		items = append(items, usuario_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const usuariosPorIDs = `-- name: UsuariosPorIDs :many
SELECT id, nombre FROM nucleo.usuarios WHERE id = ANY($1::bigint[])
`

type UsuariosPorIDsRow struct {
	ID     int64
	Nombre string
}

func (q *Queries) UsuariosPorIDs(ctx context.Context, ids []int64) ([]UsuariosPorIDsRow, error) {
	rows, err := q.db.Query(ctx, usuariosPorIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsuariosPorIDsRow
	for rows.Next() {
		var i UsuariosPorIDsRow
		if err := rows.Scan(&i.ID, &i.Nombre); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

