const zonasDeCuadrillas = `-- name: ZonasDeCuadrillas :many
SELECT cuadrilla_id, zona_id, created_at, updated_at FROM agenda.cuadrilla_zonas WHERE cuadrilla_id = ANY($1::bigint[]) ORDER BY cuadrilla_id, zona_id
`

func (q *Queries) ZonasDeCuadrillas(ctx context.Context, cuadrillas []int64) ([]AgendaCuadrillaZona, error) {
	rows, err := q.db.Query(ctx, zonasDeCuadrillas, cuadrillas)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AgendaCuadrillaZona
	for rows.Next() {
		var i AgendaCuadrillaZona
		if err := rows.Scan(
			&i.CuadrillaID,
			&i.ZonaID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

